#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Fill a HWPX (zip) template with JSON values.

- Reads /root/training_feedback.json
- Copies /root/training_feedback_template.hwpx -> /root/training_feedback_ready.hwpx
- Replaces {{...}} placeholders in XML content files
- Removes linesegarray elements in paragraphs whose text changed (prevents overlap)
"""

from __future__ import annotations

import json
import os
import re
import shutil
import sys
import zipfile
from dataclasses import dataclass
from typing import Dict, Tuple, Iterable

TEMPLATE_PATH = "/root/training_feedback_template.hwpx"
JSON_PATH = "/root/training_feedback.json"
OUTPUT_PATH = "/root/training_feedback_ready.hwpx"


def _load_json(path: str) -> Dict[str, object]:
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def _digits_only(value: object) -> str:
    # If it's already numeric, coerce to int then string.
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return str(int(value))
    s = str(value)
    return re.sub(r"[^0-9]", "", s)


def _format_satisfaction(value: object) -> str:
    # Accept values like "4.5/5.0" or 4.5.
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        score = str(value)
    else:
        s = str(value)
        m = re.search(r"([0-9]+(?:\.[0-9]+)?)", s)
        score = m.group(1) if m else s.strip()
    return f"{score}점 (5.0점 만점)"


def _format_overall_opinion(value: object) -> str:
    base = str(value).strip()
    suffix = "후속 심화반 검토 요망."
    if not base:
        return suffix
    # Ensure exactly one space before the suffix.
    if base.endswith(" "):
        return base + suffix
    return base + " " + suffix


def build_replacements(data: Dict[str, object]) -> Dict[str, str]:
    repl: Dict[str, str] = {}
    for k, v in data.items():
        repl[k] = "" if v is None else str(v)

    # Apply required transformations.
    if "참석자수" in data:
        repl["참석자수"] = _digits_only(data["참석자수"])
    if "만족도" in data:
        repl["만족도"] = _format_satisfaction(data["만족도"])
    if "종합의견" in data:
        repl["종합의견"] = _format_overall_opinion(data["종합의견"])

    return repl


def _localname(tag: str) -> str:
    if tag is None:
        return ""
    if "}" in tag:
        return tag.split("}", 1)[1]
    if ":" in tag:
        return tag.split(":", 1)[1]
    return tag


def _get_paragraph_text(elem) -> str:
    # Text is stored in descendant <...:t> elements.
    parts = []
    for t in elem.iter():
        if _localname(t.tag) == "t" and t.text:
            parts.append(t.text)
    return "".join(parts)


def _remove_linesegarrays_in_modified_paragraphs(original_xml: bytes, modified_xml: bytes) -> Tuple[bytes, int]:
    """Return (cleaned_xml_bytes, removed_count)."""

    try:
        from lxml import etree  # type: ignore

        def parse(b: bytes):
            return etree.fromstring(b)

        orig_root = parse(original_xml)
        mod_root = parse(modified_xml)

        def paragraphs(root):
            return root.xpath('//*[translate(local-name(),"ABCDEFGHIJKLMNOPQRSTUVWXYZ","abcdefghijklmnopqrstuvwxyz")="p"]')

        orig_by_id: Dict[str, str] = {}
        for p in paragraphs(orig_root):
            pid = p.get("id")
            if pid is None:
                continue
            orig_by_id[pid] = _get_paragraph_text(p)

        removed = 0
        for p in paragraphs(mod_root):
            pid = p.get("id")
            if pid is None:
                continue
            before = orig_by_id.get(pid)
            after = _get_paragraph_text(p)
            if before is None:
                continue
            if before == after:
                continue

            # Remove any descendant linesegarray/lineSegArray elements.
            targets = p.xpath(
                './/*[translate(local-name(),"ABCDEFGHIJKLMNOPQRSTUVWXYZ","abcdefghijklmnopqrstuvwxyz")="linesegarray"]'
            )
            for t in targets:
                parent = t.getparent()
                if parent is not None:
                    parent.remove(t)
                    removed += 1

        out = etree.tostring(mod_root, xml_declaration=True, encoding="utf-8")
        return out, removed

    except Exception:
        # Fallback to stdlib ElementTree.
        import xml.etree.ElementTree as ET

        orig_root = ET.fromstring(original_xml)
        mod_root = ET.fromstring(modified_xml)

        orig_by_id: Dict[str, str] = {}
        for p in mod_root.iter():
            # We'll build orig_by_id by walking original too, but keep code simple.
            pass
        for p in orig_root.iter():
            if _localname(p.tag).lower() == "p":
                pid = p.attrib.get("id")
                if pid is not None:
                    orig_by_id[pid] = _get_paragraph_text(p)

        # Parent map for removal.
        parent_map = {c: p for p in mod_root.iter() for c in p}

        removed = 0
        for p in mod_root.iter():
            if _localname(p.tag).lower() != "p":
                continue
            pid = p.attrib.get("id")
            if pid is None:
                continue
            before = orig_by_id.get(pid)
            after = _get_paragraph_text(p)
            if before is None or before == after:
                continue

            # Find descendants named linesegarray (case-insensitive).
            for node in list(p.iter()):
                if _localname(node.tag).lower() == "linesegarray":
                    parent = parent_map.get(node)
                    if parent is not None:
                        parent.remove(node)
                        removed += 1

        out = ET.tostring(mod_root, encoding="utf-8", xml_declaration=True)
        return out, removed


@dataclass
class XmlEditResult:
    new_bytes: bytes
    changed: bool
    removed_linesegarrays: int


def process_xml(xml_bytes: bytes, replacements: Dict[str, str]) -> XmlEditResult:
    try:
        xml_text = xml_bytes.decode("utf-8")
    except UnicodeDecodeError:
        # HWPX content is typically UTF-8; fallback defensively.
        xml_text = xml_bytes.decode("utf-16")

    if "{{" not in xml_text:
        return XmlEditResult(new_bytes=xml_bytes, changed=False, removed_linesegarrays=0)

    original_text = xml_text
    for key, val in replacements.items():
        xml_text = xml_text.replace("{{" + key + "}}", val)

    if xml_text == original_text:
        return XmlEditResult(new_bytes=xml_bytes, changed=False, removed_linesegarrays=0)

    modified_bytes = xml_text.encode("utf-8")
    cleaned_bytes, removed = _remove_linesegarrays_in_modified_paragraphs(
        original_xml=xml_bytes,
        modified_xml=modified_bytes,
    )
    return XmlEditResult(new_bytes=cleaned_bytes, changed=True, removed_linesegarrays=removed)


def main() -> int:
    for p in (TEMPLATE_PATH, JSON_PATH):
        if not os.path.exists(p):
            print(f"ERROR: missing required input: {p}", file=sys.stderr)
            return 2

    data = _load_json(JSON_PATH)
    replacements = build_replacements(data)

    # Step 1: copy template to output path.
    shutil.copyfile(TEMPLATE_PATH, OUTPUT_PATH)

    tmp_out = OUTPUT_PATH + ".tmp"

    modified_files = []
    removed_linesegarrays_total = 0

    with zipfile.ZipFile(OUTPUT_PATH, "r") as zin, zipfile.ZipFile(
        tmp_out, "w"
    ) as zout:
        for info in zin.infolist():
            src_bytes = zin.read(info.filename)
            out_bytes = src_bytes

            # Modify only XMLs (primarily under Contents/) that may contain placeholders.
            if info.filename.lower().endswith(".xml"):
                result = process_xml(src_bytes, replacements)
                out_bytes = result.new_bytes
                if result.changed:
                    modified_files.append(info.filename)
                    removed_linesegarrays_total += result.removed_linesegarrays

            # Preserve metadata/compression as much as zipfile allows.
            new_info = zipfile.ZipInfo(filename=info.filename, date_time=info.date_time)
            new_info.compress_type = info.compress_type
            new_info.comment = info.comment
            new_info.create_system = info.create_system
            new_info.create_version = info.create_version
            new_info.extract_version = info.extract_version
            new_info.flag_bits = info.flag_bits
            new_info.internal_attr = info.internal_attr
            new_info.external_attr = info.external_attr

            zout.writestr(new_info, out_bytes, compress_type=info.compress_type)

    os.replace(tmp_out, OUTPUT_PATH)

    # Verification: ensure no placeholders remain.
    remaining_placeholders = []
    with zipfile.ZipFile(OUTPUT_PATH, "r") as z:
        for name in z.namelist():
            if not name.lower().endswith(".xml"):
                continue
            b = z.read(name)
            try:
                t = b.decode("utf-8")
            except UnicodeDecodeError:
                t = b.decode("utf-16")
            if "{{" in t:
                remaining_placeholders.append(name)

    if remaining_placeholders:
        print("ERROR: placeholders still remain in:")
        for n in remaining_placeholders:
            print(" -", n)
        return 3

    # Print summary.
    print("Output written:", OUTPUT_PATH)
    print("Modified XML files:", modified_files if modified_files else "(none)")
    print("Removed linesegarray elements:", removed_linesegarrays_total)
    print("\nReplaced values:")
    for k in sorted(replacements.keys()):
        print(f" - {k}: {replacements[k]}")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())

