import zipfile
import xml.etree.ElementTree as ET
from collections import defaultdict

template='/root/training_feedback_template.hwpx'
out='/root/training_feedback_ready.hwpx'


def local(tag: str) -> str:
    if '}' in tag:
        return tag.split('}',1)[1]
    if ':' in tag:
        return tag.split(':',1)[1]
    return tag

def paragraph_text(p) -> str:
    parts=[]
    for node in p.iter():
        if local(node.tag)=='t' and (node.text or ''):
            parts.append(node.text)
    return ''.join(parts)

def find_linesegarray(p):
    for node in p.iter():
        if local(node.tag).lower()=='linesegarray':
            return True
    return False

def collect_paragraphs(zip_path):
    by_file=defaultdict(dict)
    with zipfile.ZipFile(zip_path,'r') as z:
        for name in z.namelist():
            if not name.lower().endswith('.xml'):
                continue
            root=ET.fromstring(z.read(name))
            for p in root.iter():
                if local(p.tag).lower()!='p':
                    continue
                pid=p.attrib.get('id')
                if pid is None:
                    continue
                by_file[name][pid]= {
                    'text': paragraph_text(p),
                    'has_linesegarray': find_linesegarray(p),
                }
    return by_file

tmpl=collect_paragraphs(template)
outp=collect_paragraphs(out)

modified=[]
violations=[]

for fname, pmap in tmpl.items():
    for pid, info in pmap.items():
        t_text=info['text']
        o=outp.get(fname, {}).get(pid)
        if not o:
            continue
        o_text=o['text']
        if t_text != o_text:
            modified.append((fname,pid,t_text,o_text,o['has_linesegarray']))
            if o['has_linesegarray']:
                violations.append((fname,pid,o_text))

print('Modified paragraphs:', len(modified))
print('Modified paragraphs with linesegarray (should be 0):', len(violations))
if violations:
    for v in violations:
        print('VIOLATION', v[0], 'p id', v[1], 'text=', v[2])

# Also report which paragraphs still have linesegarray (should be only unmodified)
remaining=[]
for fname, pmap in outp.items():
    for pid, info in pmap.items():
        if info['has_linesegarray']:
            remaining.append((fname,pid,info['text']))
print('\nRemaining linesegarray paragraphs:', len(remaining))
for fname,pid,text in sorted(remaining):
    print('-', fname, 'p', pid, ':', text)
